    /* ---------------------------------------------------- Error Boundary */

    class ChiefErrorBoundary extends React.Component {
      constructor(props) {
        super(props)
        this.state = { error: null }
      }
      static getDerivedStateFromError(error) {
        return { error }
      }
      componentDidCatch(error, info) {
        console.error('dsh-chief view boundary caught error:', error, info)
      }
      render() {
        if (this.state.error) {
          return h(
            'div',
            { className: 'dnb-group', style: { padding: 16, textAlign: 'center', marginTop: 12 } },
            h('div', { style: { fontWeight: 500, fontSize: 13, marginBottom: 6 } }, '视图渲染已自动恢复保护'),
            h('div', { style: { fontSize: 11.5, color: 'var(--dnb-text-2)', marginBottom: 12, wordBreak: 'break-word' } },
              String(this.state.error && this.state.error.message ? this.state.error.message : this.state.error)),
            h('button', {
              className: 'dnb-primary-btn',
              onClick: () => {
                this.setState({ error: null })
                void refresh()
              },
            }, '重新加载'),
          )
        }
        return this.props.children
      }
    }

    /* ----------------------------------------------------- iOS Micro-Flat CSS */

    function Switch({ checked, onChange, disabled = false, title = '', small = false, tone = '' }) {
      return h(
        'button',
        {
          type: 'button',
          role: 'switch',
          disabled: Boolean(disabled),
          'aria-checked': checked ? 'true' : 'false',
          'aria-disabled': disabled ? 'true' : 'false',
          'data-disabled': disabled ? '1' : '0',
          'data-tone': tone || undefined,
          title: title || undefined,
          className: 'dnb-switch',
          'data-on': checked ? '1' : '0',
          style: small ? { transform: 'scale(0.82)', transformOrigin: 'center' } : undefined,
          onClick: () => {
            if (disabled) return
            onChange(!checked)
          },
        },
        h('span', { className: 'dnb-switch-thumb' }),
      )
    }

    function SearchDrawer({ view }) {
      if (!view.searchOpen) return null
      const run = () => {
        const text = (view.askText || '').trim()
        if (!text) return
        const hits = searchBoard(text)
        patch({ askHits: hits, askNote: '' })
      }
      const askModel = () => {
        const text = (view.askText || '').trim()
        if (!text) return
        patch({ secInput: text, secTarget: 'auto', searchOpen: false, askHits: null })
        void submitChiefBar()
      }

      return h(
        'div',
        { style: { padding: '0 12px 8px', flexShrink: 0 }, className: 'dnb-view' },
        h(
          'div',
          { style: { display: 'flex', gap: 6, alignItems: 'center' } },
          h('input', {
            className: 'dnb-input',
            style: { borderRadius: 99, paddingLeft: 12, height: 30 },
            placeholder: bi('搜索记忆、任务、协同信箱…', 'Search facts, tasks, mailbox…'),
            autoFocus: true,
            value: view.askText || '',
            onChange: e => {
              const val = e.target.value
              patch({ askText: val, askHits: val.trim() ? searchBoard(val) : null })
            },
            onKeyDown: e => {
              if (e.key === 'Enter') run()
              if (e.key === 'Escape') patch({ searchOpen: false, askHits: null })
            },
          }),
          (view.askText || '').trim()
            ? h('button', {
                className: 'dnb-pill',
                style: { height: 30 },
                disabled: view.archiveSearchBusy,
                onClick: () => void searchColdArchives(view.askText),
                title: bi('按需穿透搜索封存懒加载的长期工程档案柜', 'Search cold engineering archive vaults on demand'),
              }, h(Icon, { name: 'archive', size: 12 }), view.archiveSearchBusy ? bi('检索中…', 'Searching…') : bi('搜档案柜', 'Vaults'))
            : null,
          (view.askText || '').trim()
            ? h('button', {
                className: 'dnb-pill dnb-pill-accent',
                style: { height: 30 },
                onClick: askModel,
                title: bi('直接交给 DSH 参谋长回答或拆话', 'Ask DSH Chief directly'),
              }, h(Icon, { name: 'sparkles', size: 12 }), bi('问参谋长', 'Ask Chief'))
            : null,
        ),
        Array.isArray(view.askHits)
          ? h(
              'div',
              { className: 'dnb-group', style: { marginTop: 6, marginBottom: 0, maxHeight: 180, overflow: 'auto' } },
              view.askHits.length
                ? view.askHits.map((item, idx) =>
                    h(
                      'div',
                      {
                        key: item.id + '-' + idx,
                        className: 'dnb-cell dnb-cell-hover',
                        style: { cursor: 'pointer', padding: '7px 12px' },
                        onClick: () => {
                          const nextPatch = { tab: item.tab || 'chief', searchOpen: false }
                          if (item.subTab) nextPatch.secSubTab = item.subTab
                          if (item.showRawTurns) nextPatch.secShowRawTurns = true
                          if (item.tab === 'tasks') nextPatch.selectedTaskId = item.id
                          if (item.tab === 'archive' && item.archiveId) {
                            nextPatch.archiveOpenFolders = { ...(store.archiveOpenFolders || {}), ...(item.folderId ? { [item.folderId]: true } : {}) }
                            nextPatch.archiveOpenFiles = { ...(store.archiveOpenFiles || {}), [item.archiveId]: true }
                            patch(nextPatch)
                            void loadArchives(false)
                            void loadArchiveDetail(item.archiveId, false)
                            return
                          }
                          patch(nextPatch)
                        },
                      },
                      h('span', { className: 'dnb-tag', style: { color: 'var(--dnb-accent)' } }, item.kind),
                      h('div', { style: { flex: 1, minWidth: 0 } },
                        h('div', { style: { fontWeight: 500, fontSize: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, item.title),
                        item.snippet ? h('div', { style: { fontSize: 11, color: 'var(--dnb-text-3)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, item.snippet) : null,
                      ),
                    ),
                  )
                : h('div', { style: { padding: '10px 12px', fontSize: 11.5, color: 'var(--dnb-text-3)', textAlign: 'center' } }, bi('无匹配结果', 'No matches found')),
            )
          : null,
      )
    }

    /* ----------------------------- Status Badge & Objective Radar Strip */

    function StatusBadge({ status, style }) {
      const st = STATUSES.includes(status) ? status : 'todo'
      return h(
        'span',
        { className: 'dnb-status-badge', 'data-status': st, style },
        st === 'doing'
          ? h('span', { className: 'dnb-spin-ring', style: { '--dnb-spin-size': '9.5px', color: '#409cff' } })
          : null,
        statusBadge(st) || STATUS_BADGE[st] || STATUS_LABEL[st],
      )
    }

    /**
     * Prominent radar strip highlighting Advancing (`doing`) and Blocked (`blocked`) objectives.
     * Clicking any card jumps straight to the Pyramid Tree view and frames the active subagents!
     */
    function ObjectiveRadarStrip({ board, compact = false }) {
      const allTasks = (board && Array.isArray(board.tasks)) ? board.tasks.filter(Boolean) : []
      const blockedTasks = allTasks.filter(t => t.status === 'blocked')
      const doingTasks = allTasks.filter(t => t.status === 'doing')
      const subagents = Array.isArray(store.subagents) ? store.subagents : []
      const identity = store.agentIdentity || null

      if (!blockedTasks.length && !doingTasks.length) return null

      const items = [
        ...blockedTasks.map(t => ({ task: t, kind: 'blocked' })),
        ...doingTasks.map(t => ({ task: t, kind: 'doing' })),
      ]

      return h(
        'div',
        { className: 'dnb-radar-strip' },
        items.slice(0, compact ? 3 : 6).map(({ task, kind }) => {
          const isFocused = store.focusTaskId === task.id
            && store.tab === 'tasks'
            && (store.taskViewMode === 'graph' || store.taskViewMode === 'canvas')
          const resolved = resolveTaskAgents(task, allTasks, subagents, identity)
          const agentLabels = resolved.agentNames.length
            ? resolved.agentNames.slice(0, 2).map(n => '@' + shortAgentName(n, true)).join('、')
              + (resolved.agentNames.length > 2 ? ' 等 ' + resolved.agentNames.length + ' 代理' : '')
            : '@主代理'
          const subReason = kind === 'blocked' && (task.note || (board && board.cursor && board.cursor.blocked))
            ? clampTitle(task.note || board.cursor.blocked, 20)
            : ''

          return h(
            'div',
            {
              key: task.id,
              className: 'dnb-radar-card',
              'data-kind': kind,
              'data-focused': isFocused ? '1' : '0',
              title: kind === 'blocked'
                ? '受阻目标：点击跳转金字塔视角定位负责子代理'
                : '推进目标：点击跳转金字塔视角框选正在推进的子代理',
              onClick: () => {
                if (isFocused) {
                  patch({ focusTaskId: '' })
                } else {
                  focusObjectiveInPyramid(task.id)
                }
              },
            },
            h(StatusBadge, { status: kind }),
            h(
              'div',
              { style: { flex: 1, minWidth: 0 } },
              h(
                'div',
                {
                  style: {
                    fontWeight: 600,
                    fontSize: 12.5,
                    color: 'var(--dnb-text)',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  },
                },
                task.title || task.id,
              ),
              h(
                'div',
                {
                  style: {
                    fontSize: 11,
                    color: kind === 'blocked' ? 'rgba(255, 110, 100, 0.92)' : 'var(--dnb-text-2)',
                    marginTop: 1.5,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  },
                },
                (kind === 'blocked' ? '受阻关联：' : '推进代理：') + agentLabels + (subReason ? ' · ' + subReason : ''),
              ),
            ),
            h(
              'span',
              {
                className: 'dnb-pill',
                style: {
                  height: 23,
                  padding: '0 8px',
                  fontSize: 10.5,
                  color: isFocused ? '#fff' : (kind === 'blocked' ? '#ff453a' : '#409cff'),
                  background: isFocused
                    ? (kind === 'blocked' ? '#ff453a' : '#0a84ff')
                    : (kind === 'blocked' ? 'rgba(255,69,58,0.12)' : 'rgba(10,132,255,0.12)'),
                  borderColor: kind === 'blocked' ? 'rgba(255,69,58,0.38)' : 'rgba(10,132,255,0.38)',
                  flexShrink: 0,
                },
              },
              h(Icon, { name: 'target', size: 11.5 }),
              isFocused ? '已框选' : '看代理',
            ),
          )
        }),
      )
    }

    /* ---------------------------------------------------- Subagent Fleet Bar */

    function SubagentFleetBar({ board }) {
      const subagents = Array.isArray(store.subagents) ? store.subagents : []
      const [steerAgent, setSteerAgent] = React.useState('')
      const [steerText, setSteerText] = React.useState('')
      const hier = buildAgentHierarchy(subagents, store.agentIdentity)
      const children = hier.children
      const runningCount = children.filter(a => a.status === 'running').length

      const activeAgentObj = children.find(a => a.name === steerAgent) || null

      const sendSteer = () => {
        const msg = steerText.trim()
        if (!steerAgent || !msg) return
        setSteerText('')
        void act({ action: 'team.steer', agent: steerAgent, message: msg })
      }

      if (!children.length && !store.showInternalProbes) return null

      const isCollapsed = Boolean(store.fleetCollapsed)
      const hasMany = children.length > 10
      const showAll = Boolean(store.fleetShowAll)
      const hasAnyProbe = hier.probeCount > 0 || (store.showInternalProbes && hier.allChildren.some(a => isInternalProbeName(a.name)))

      // Determine visible pills when expanded in smart-compact mode
      let visibleAgents = children
      let hiddenCount = 0
      if (!isCollapsed && hasMany && !showAll) {
        const allTasks = (board && Array.isArray(board.tasks)) ? board.tasks : []
        const busyNames = new Set(
          allTasks
            .filter(t => t && t.status !== 'done')
            .map(t => {
              const hit = hier.matchAgentRef(t.subagent || t.owner || t.session)
              return hit ? hit.name : ''
            })
            .filter(Boolean),
        )
        const priority = children.filter(
          a => a.status === 'running' || busyNames.has(a.name) || a.name === store.filterAgent || a.name === steerAgent,
        )
        visibleAgents = priority.length > 0 ? priority : children.slice(-3)
        hiddenCount = Math.max(0, children.length - visibleAgents.length)
      }

      return h(
        'div',
        { className: 'dnb-group', style: { padding: isCollapsed ? '7px 10px' : '8px 10px', marginBottom: 10 } },
        h(
          'div',
          { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6, marginBottom: isCollapsed ? 0 : 6 } },
          h(
            'div',
            {
              style: {
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                fontSize: 11.5,
                fontWeight: 600,
                color: 'var(--dnb-text-2)',
                cursor: 'pointer',
                minWidth: 0,
              },
              onClick: () => patch({ fleetCollapsed: !isCollapsed }),
              title: isCollapsed ? '点击展开子代理团队' : '点击收起子代理团队',
            },
            runningCount > 0
              ? h('span', { className: 'dnb-spin-ring', style: { '--dnb-spin-size': '8px', color: '#409cff' } })
              : h('span', {
                  style: {
                    width: 7,
                    height: 7,
                    borderRadius: '50%',
                    background: 'var(--dnb-text-3)',
                    flexShrink: 0,
                  },
                }),
            '子代理团队',
            h(
              'span',
              { style: { color: runningCount > 0 ? '#409cff' : 'var(--dnb-text-3)', fontWeight: 500 } },
              runningCount ? `${runningCount} 运行中 · 共 ${children.length}` : `共 ${children.length} 成员`,
            ),
          ),
          h(
            'div',
            { style: { display: 'flex', alignItems: 'center', gap: 5, flexShrink: 0 } },
            store.filterAgent
              ? h('button', {
                  className: 'dnb-pill',
                  style: { height: 22, fontSize: 11, padding: '0 8px' },
                  onClick: () => { patch({ filterAgent: '' }); setSteerAgent('') },
                }, '清除筛选')
              : null,
            h('button', {
              className: 'dnb-pill',
              style: { height: 22, fontSize: 11, padding: '0 8px' },
              onClick: () => patch({ fleetCollapsed: !isCollapsed }),
            },
              isCollapsed ? `展示 (${children.length})` : '收起',
              h(Icon, {
                name: 'chevron',
                size: 11,
                style: {
                  transform: isCollapsed ? 'rotate(90deg)' : 'rotate(-90deg)',
                  transition: 'transform 0.16s ease',
                },
              }),
            ),
          ),
        ),
        !isCollapsed
          ? h(
              'div',
              { style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' } },
              visibleAgents.map(agent => {
                const isRunning = agent.status === 'running'
                const isSelected = store.filterAgent === agent.name || steerAgent === agent.name
                const pKey = hier.parentKeyOf.get(agent.name)
                const isTier2 = pKey && pKey !== 'lead'
                return h(
                  'button',
                  {
                    key: agent.name,
                    className: 'dnb-pill',
                    'data-active': isSelected ? '1' : '0',
                    style: {
                      height: 25,
                      padding: '0 9px',
                      borderColor: isRunning && !isSelected ? 'rgba(10, 132, 255, 0.38)' : undefined,
                    },
                    title: '@' + agent.name + (isTier2 ? '（上级：@' + pKey + '）' : '') + (agent.description ? ' — ' + agent.description : ''),
                    onClick: () => {
                      const next = store.filterAgent === agent.name ? '' : agent.name
                      patch({ filterAgent: next })
                      setSteerAgent(steerAgent === agent.name ? '' : agent.name)
                    },
                  },
                  isRunning
                    ? h('span', { className: 'dnb-spin-ring', style: { '--dnb-spin-size': '8px', color: '#409cff' } })
                    : h('span', {
                        style: {
                          width: 6.5,
                          height: 6.5,
                          borderRadius: '50%',
                          background: 'var(--dnb-text-3)',
                        },
                      }),
                  '@' + shortAgentName(agent.name),
                )
              }),
              hiddenCount > 0
                ? h('button', {
                    className: 'dnb-pill',
                    style: { height: 25, padding: '0 9px', fontSize: 11, borderStyle: 'dashed', color: 'var(--dnb-text-3)' },
                    title: '展示其余已结束/待命的子代理成员',
                    onClick: () => patch({ fleetShowAll: true }),
                  }, '+' + hiddenCount + ' 展示全部')
                : (hasMany && showAll
                    ? h('button', {
                        className: 'dnb-pill',
                        style: { height: 25, padding: '0 9px', fontSize: 11, color: 'var(--dnb-text-3)' },
                        onClick: () => patch({ fleetShowAll: false }),
                      }, '折叠空闲')
                    : null),
              hasAnyProbe
                ? h('button', {
                    className: 'dnb-pill',
                    'data-active': store.showInternalProbes ? '1' : '0',
                    style: { height: 24, padding: '0 8px', fontSize: 10.5, borderStyle: 'dashed', opacity: 0.78 },
                    title: store.showInternalProbes ? '隐藏后台记忆检查点探针 (@mnemon-review)' : '显示后台记忆检查点探针 (@mnemon-review)',
                    onClick: () => patch({ showInternalProbes: !store.showInternalProbes }),
                  }, store.showInternalProbes ? '隐藏内部探针' : `内部探针 (${hier.probeCount})`)
                : null,
            )
          : null,
        !isCollapsed && steerAgent
          ? h(
              'div',
              { style: { display: 'flex', gap: 6, alignItems: 'center', marginTop: 8, paddingTop: 8, borderTop: '1px solid var(--dnb-border)' } },
              activeAgentObj && activeAgentObj.id
                ? h('button', {
                    className: 'dnb-pill',
                    style: { height: 28 },
                    title: '在分栏打开该子代理对话',
                    onClick: () => {
                      if (!openSubagentChat(activeAgentObj)) {
                        patch({ notice: '当前子代理尚未建立独立会话视图' })
                      }
                    },
                  }, h(Icon, { name: 'chat', size: 12 }), '对话')
                : null,
              h('input', {
                className: 'dnb-input',
                style: { flex: 1, height: 28, padding: '0 10px', borderRadius: 99, fontSize: 11.5 },
                placeholder: '给 @' + shortAgentName(steerAgent) + ' 发指令…',
                value: steerText,
                onChange: e => setSteerText(e.target.value),
                onKeyDown: e => { if (e.key === 'Enter') sendSteer() },
              }),
              h('button', {
                className: 'dnb-primary-btn',
                style: { height: 28, padding: '0 10px' },
                disabled: !steerText.trim(),
                onClick: sendSteer,
              }, '发送'),
              h('button', {
                className: 'dnb-pill dnb-pill-danger',
                style: { height: 28, padding: '0 8px' },
                title: '停止当前轮次',
                onClick: () => void act({ action: 'team.interrupt', agent: steerAgent }),
              }, h(Icon, { name: 'stop', size: 11 })),
            )
          : null,
      )
    }

    /* ----------------------------------------------- Bottom Sheet Inspector */

    function classifyBulletTagTone(tag) {
      const t = String(tag || '')
      if (
        /禁止|红线|受阻|错误|失败|撞墙|高危|违规|严禁|崩溃|死锁/.test(t)
        || (/风险|告警|异常/.test(t) && !/保障|兜底|已解|可控|无风险|解除/.test(t))
      ) {
        return { bg: 'rgba(255, 69, 58, 0.16)', fg: '#ff6961', border: 'rgba(255, 69, 58, 0.30)', spinning: false }
      }
      if (/完成|已完|结论|必做|允许|已解|就绪|已验证|通过|已执行|已处理|兜底|保障|达成/.test(t)) {
        return { bg: 'rgba(48, 209, 88, 0.15)', fg: '#30d158', border: 'rgba(48, 209, 88, 0.28)', spinning: false }
      }
      if (/待办|待收尾|待推进|未完|未开始|待定|搁置|排队|空闲|休眠/.test(t)) {
        return { bg: 'rgba(142, 142, 147, 0.16)', fg: '#a1a1aa', border: 'rgba(142, 142, 147, 0.26)', spinning: false }
      }
      if (/注意|提醒|警告|警惕|纪律|顺序|验收|待验|核对|原因|约束|谨慎|观察|复核|风险/.test(t)) {
        return { bg: 'rgba(245, 158, 11, 0.16)', fg: '#fbbf24', border: 'rgba(245, 158, 11, 0.30)', spinning: false }
      }
      if (/推进|进行中|执行中|运行中|处理中|排查中|构建中|同步中|验证中/.test(t)) {
        return { bg: 'rgba(10, 132, 255, 0.16)', fg: '#409cff', border: 'rgba(10, 132, 255, 0.32)', spinning: true }
      }
      return { bg: 'rgba(10, 132, 255, 0.14)', fg: '#409cff', border: 'rgba(10, 132, 255, 0.26)', spinning: false }
    }

    function classifySectionHeadingTone(heading) {
      const s = String(heading || '')
      const hasWarn = /纪律|边界|注意|提醒|警告|风险|约束|验收|待验/.test(s)
      const hasRed = /禁止|红线|受阻|阻塞|错误|告警|故障/.test(s)
      if (hasWarn && hasRed) {
        return { fg: '#fbbf24', bar: 'linear-gradient(180deg, #f59e0b 0%, #ff453a 100%)' }
      }
      if (hasRed) {
        return { fg: '#ff6961', bar: '#ff453a' }
      }
      if (hasWarn) {
        return { fg: '#fbbf24', bar: '#f59e0b' }
      }
      if (/已完成|达成|放行|收口/.test(s)) {
        return { fg: '#34d399', bar: '#30d158' }
      }
      if (/待办|未完成|遗留|后续/.test(s)) {
        return { fg: '#a1a1aa', bar: '#8e8e93' }
      }
      return { fg: '#60a5fa', bar: '#0a84ff' }
    }

    function renderStructuredHeading(heading, compact) {
      if (!heading) return null
      const tone = classifySectionHeadingTone(heading)
      return h(
        'div',
        { className: compact ? 'dnb-struct-head is-compact' : 'dnb-struct-head', style: { color: tone.fg } },
        h('span', { className: 'dnb-struct-bar', style: { background: tone.bar } }),
        h('span', null, heading),
      )
    }

    function splitTaggedBullet(rawLine) {
      const clean = String(rawLine || '')
        .replace(/\[dsh-mnemon:[^\]]*\][\s\S]*/gi, '')
        .replace(/^[-*•]\s+/, '')
        .replace(/^\d+[.)、]\s+/, '')
        .trim()
      if (!clean) return null
      const m = clean.match(/^【([^】]{1,12})】\s*(.*)$/)
      if (m) {
        return { badge: m[1].trim(), body: m[2].trim() || m[1].trim() }
      }
      return { badge: '', body: clean }
    }

    function parseNarrativeBlocks(raw) {
      const text = String(raw || '').trim()
      if (!text) return []
      const lines = text.split(/\r?\n/)
      const blocks = []
      let current = null

      const ensureBlock = () => {
        if (!current) current = { heading: '', items: [] }
        return current
      }

      for (const rawLine of lines) {
        const line = rawLine.trim()
        if (!line) continue
        if (/^\[dsh-mnemon:/i.test(line)) continue
        const headingMatch = line.match(/^#{1,3}\s+(.+)$/)
        if (headingMatch) {
          if (current && (current.heading || current.items.length)) blocks.push(current)
          current = { heading: headingMatch[1].trim(), items: [] }
          continue
        }
        if (/^(?:[-*•]|\d+[.)、])\s+/.test(line) || /^【[^】]{1,12}】/.test(line)) {
          const parsed = splitTaggedBullet(line)
          if (parsed) ensureBlock().items.push({ kind: 'bullet', ...parsed })
        } else {
          const cleanedPara = line
            .replace(/\[dsh-mnemon:[^\]]*\][\s\S]*/gi, '')
            .trim()
          if (!cleanedPara) continue
          ensureBlock().items.push({ kind: 'para', body: cleanedPara })
        }
      }
      if (current && (current.heading || current.items.length)) blocks.push(current)
      return blocks
    }

    function renderStructuredItem(item, key) {
      if (!item) return null
      if (item.kind === 'bullet') {
        const tone = item.badge ? classifyBulletTagTone(item.badge) : null
        return h(
          'div',
          {
            key,
            style: {
              display: 'flex',
              alignItems: 'flex-start',
              gap: 7,
              padding: '3.5px 0',
              fontSize: 12.2,
              lineHeight: 1.52,
              color: 'var(--dnb-text)',
            },
          },
          item.badge
            ? h(
                'span',
                {
                  style: {
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: 4.5,
                    padding: '1px 6.5px',
                    borderRadius: 6,
                    fontSize: 10.5,
                    fontWeight: 700,
                    background: tone.bg,
                    color: tone.fg,
                    border: '1px solid ' + tone.border,
                    flexShrink: 0,
                    marginTop: 1.5,
                  },
                },
                tone.spinning
                  ? h('span', { className: 'dnb-spin-ring', style: { '--dnb-spin-size': '9px', color: tone.fg } })
                  : null,
                item.badge,
              )
            : h('span', {
                style: {
                  width: 5,
                  height: 5,
                  borderRadius: '50%',
                  background: 'var(--dnb-accent)',
                  flexShrink: 0,
                  marginTop: 7,
                },
              }),
          h('span', { style: { flex: 1, minWidth: 0, wordBreak: 'break-word' } }, item.body),
        )
      }
      return h('p', { key, className: 'dnb-prose-p' }, item.body)
    }

    function renderStructuredText(rawText) {
      const blocks = parseNarrativeBlocks(rawText)
      if (!blocks.length) {
        return h('div', { style: { whiteSpace: 'pre-wrap', wordBreak: 'break-word' } }, String(rawText || ''))
      }
      return h(
        'div',
        { style: { display: 'flex', flexDirection: 'column', gap: 4 } },
        blocks.map((blk, bi) =>
          h(
            'div',
            { key: bi, style: { marginTop: bi === 0 ? 0 : 6 } },
            blk.heading ? renderStructuredHeading(blk.heading, true) : null,
            blk.items.map((it, ii) => renderStructuredItem(it, `${bi}-${ii}`)),
          ),
        ),
      )
    }

    function parseSixGoalBrief(raw) {
      const text = String(raw || '').trim()
      if (!text) return null
      const rowsByKey = {}
      for (const rawLine of text.split(/\r?\n/)) {
        const clean = rawLine.trim().replace(/^(?:[-*•]\s+)/, '')
        const m = clean.match(/^【([^】]{2,18})】\s*[：:]?\s*(.+)$/)
        if (!m) continue
        const tag = m[1].trim().replace(/^[^\u4e00-\u9fa5A-Za-z]+/, '').trim()
        const body = m[2].trim()
        const def = SIX_GOAL_ROWS_META.find(r => r.aliases.includes(tag))
        if (def && body && !rowsByKey[def.key]) {
          rowsByKey[def.key] = { ...def, body }
        }
      }
      const matched = SIX_GOAL_ROWS_META.filter(r => rowsByKey[r.key]).map(r => rowsByKey[r.key])
      return matched.length >= 2 ? matched : null
    }

    function orderChatHistoryNewestFirst(rawList) {
      const items = Array.isArray(rawList) ? rawList.filter(Boolean) : []
      const groups = []
      for (let i = 0; i < items.length; i += 1) {
        const cur = items[i]
        const next = items[i + 1]
        if (cur && cur.role === 'user' && next && next.role === 'chief') {
          groups.push([cur, next])
          i += 1
        } else {
          groups.push([cur])
        }
      }
      groups.reverse()
      return groups.flat()
    }

    function groupChatHistoryTurnsNewestFirst(rawList) {
      const items = Array.isArray(rawList) ? rawList.filter(Boolean) : []
      const turns = []
      let activeTurn = null
      let activeSys = null
      for (const item of items) {
        if (item.role === 'user') {
          activeSys = null
          activeTurn = {
            id: 'turn-' + (item.id || turns.length),
            kind: 'turn',
            question: item,
            replies: [],
            at: item.at || 0,
          }
          turns.push(activeTurn)
        } else if (activeTurn) {
          activeTurn.replies.push(item)
        } else {
          if (!activeSys) {
            activeSys = {
              id: 'sys-' + (item.id || turns.length),
              kind: 'system',
              question: null,
              replies: [],
              at: item.at || 0,
            }
            turns.push(activeSys)
          }
          activeSys.replies.push(item)
        }
      }
      turns.reverse()
      return turns
    }

    /* ------------------------------------------- Interactive Fan Thinking Gauge */

    const FAN_EFFORT_STEPS = [
      { key: 'off', label: '关', deg: -180, color: '#94a3b8' },
      { key: 'low', label: '低', deg: -135, color: '#38bdf8' },
      { key: 'medium', label: '中', deg: -90, color: '#6366f1' },
      { key: 'high', label: '高', deg: -45, color: '#f59e0b' },
      { key: 'xhigh', label: '极高', deg: 0, color: '#ec4899' },
    ]

    function fanPolarPoint(cx, cy, r, deg) {
      const rad = (deg * Math.PI) / 180
      return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) }
    }

    function fanDescribeArc(cx, cy, r, startDeg, endDeg) {
      if (Math.abs(endDeg - startDeg) < 0.2) return ''
      const p0 = fanPolarPoint(cx, cy, r, startDeg)
      const p1 = fanPolarPoint(cx, cy, r, endDeg)
      const large = Math.abs(endDeg - startDeg) > 180 ? 1 : 0
      return `M ${p0.x.toFixed(2)} ${p0.y.toFixed(2)} A ${r} ${r} 0 ${large} 1 ${p1.x.toFixed(2)} ${p1.y.toFixed(2)}`
    }

    function fanDescribeWedge(cx, cy, rInner, rOuter, startDeg, endDeg) {
      const o0 = fanPolarPoint(cx, cy, rOuter, startDeg)
      const o1 = fanPolarPoint(cx, cy, rOuter, endDeg)
      const i1 = fanPolarPoint(cx, cy, rInner, endDeg)
      const i0 = fanPolarPoint(cx, cy, rInner, startDeg)
      return `M ${o0.x.toFixed(2)} ${o0.y.toFixed(2)} A ${rOuter} ${rOuter} 0 0 1 ${o1.x.toFixed(2)} ${o1.y.toFixed(2)} L ${i1.x.toFixed(2)} ${i1.y.toFixed(2)} A ${rInner} ${rInner} 0 0 0 ${i0.x.toFixed(2)} ${i0.y.toFixed(2)} Z`
    }

    function fanAngleToStep(deg) {
      let best = FAN_EFFORT_STEPS[0]
      let bestDist = Infinity
      for (const step of FAN_EFFORT_STEPS) {
        const d = Math.abs(deg - step.deg)
        if (d < bestDist) {
          bestDist = d
          best = step
        }
      }
      return best
    }

    function EffortFanGauge({ value = 'auto', onChange, compact = false }) {
      const svgRef = React.useRef(null)
      const gradIdRef = React.useRef('dnb-fan-grad-' + Math.random().toString(36).slice(2, 8))
      const [dragging, setDragging] = React.useState(false)
      const [dragAngle, setDragAngle] = React.useState(null)
      const [hoverKey, setHoverKey] = React.useState('')

      const committedKey = THINKING_EFFORT_OPTIONS.some(o => o.key === value) ? value : 'auto'
      const isAuto = committedKey === 'auto'
      const committedStep = FAN_EFFORT_STEPS.find(s => s.key === committedKey) || null

      const activeAngle = dragging && dragAngle !== null
        ? dragAngle
        : (committedStep ? committedStep.deg : -90)
      const previewStep = dragging && dragAngle !== null ? fanAngleToStep(dragAngle) : committedStep
      const showManualNeedle = !isAuto || dragging

      const cx = 110
      const cy = 98
      const rTrack = 68
      const needleRotateDeg = activeAngle + 90
      const knobPt = fanPolarPoint(cx, cy, rTrack, activeAngle)

      const pointerToAngle = (clientX, clientY) => {
        const el = svgRef.current
        if (!el) return -90
        const rect = el.getBoundingClientRect()
        if (!rect.width || !rect.height) return -90
        const sx = ((clientX - rect.left) / rect.width) * 220
        const sy = ((clientY - rect.top) / rect.height) * 116
        let deg = (Math.atan2(sy - cy, sx - cx) * 180) / Math.PI
        if (deg > 90) deg = -180
        else if (deg > 0) deg = 0
        return Math.max(-180, Math.min(0, deg))
      }

      const commitKey = (nextKey) => {
        if (typeof onChange === 'function' && nextKey && nextKey !== committedKey) {
          onChange(nextKey)
        }
      }

      const handlePointerDown = (e) => {
        if (e.button !== undefined && e.button !== 0) return
        e.stopPropagation()
        const ang = pointerToAngle(e.clientX, e.clientY)
        setDragging(true)
        setDragAngle(ang)
        try {
          if (e.currentTarget && typeof e.currentTarget.setPointerCapture === 'function') {
            e.currentTarget.setPointerCapture(e.pointerId)
          }
        } catch {}
      }

      const handlePointerMove = (e) => {
        if (!dragging) return
        e.stopPropagation()
        setDragAngle(pointerToAngle(e.clientX, e.clientY))
      }

      const handlePointerUp = (e) => {
        if (!dragging) return
        e.stopPropagation()
        const ang = pointerToAngle(e.clientX, e.clientY)
        const snapped = fanAngleToStep(ang)
        setDragging(false)
        setDragAngle(null)
        try {
          if (e.currentTarget && typeof e.currentTarget.releasePointerCapture === 'function') {
            e.currentTarget.releasePointerCapture(e.pointerId)
          }
        } catch {}
        if (snapped && typeof onChange === 'function') {
          onChange(snapped.key)
        }
      }

      const handlePointerCancel = () => {
        if (!dragging) return
        setDragging(false)
        setDragAngle(null)
      }

      return h(
        'div',
        {
          className: 'dnb-fan-gauge',
          'data-compact': compact ? '1' : '0',
          onClick: e => e.stopPropagation(),
          onMouseLeave: () => setHoverKey(''),
        },
        h(
          'div',
          { className: 'dnb-fan-stage' },
          h(
            'svg',
            {
              ref: svgRef,
              className: 'dnb-fan-svg',
              'data-dragging': dragging ? '1' : '0',
              viewBox: '0 0 220 116',
              onPointerDown: handlePointerDown,
              onPointerMove: handlePointerMove,
              onPointerUp: handlePointerUp,
              onPointerCancel: handlePointerCancel,
            },
            h(
              'defs',
              null,
              h(
                'linearGradient',
                { id: gradIdRef.current, x1: '0%', y1: '50%', x2: '100%', y2: '50%' },
                h('stop', { offset: '0%', stopColor: '#94a3b8' }),
                h('stop', { offset: '26%', stopColor: '#38bdf8' }),
                h('stop', { offset: '52%', stopColor: '#6366f1' }),
                h('stop', { offset: '78%', stopColor: '#f59e0b' }),
                h('stop', { offset: '100%', stopColor: '#ec4899' }),
              ),
            ),
            // Segmented subtle track background across 5 notches
            FAN_EFFORT_STEPS.map((step, i) => {
              const prevDeg = i === 0 ? -180 : (FAN_EFFORT_STEPS[i - 1].deg + step.deg) / 2
              const nextDeg = i === FAN_EFFORT_STEPS.length - 1 ? 0 : (step.deg + FAN_EFFORT_STEPS[i + 1].deg) / 2
              const isLit = !isAuto && !dragging
                ? (committedStep && step.deg <= committedStep.deg)
                : (dragging && previewStep && step.deg <= previewStep.deg)
              return h('path', {
                key: 'seg-' + step.key,
                d: fanDescribeArc(cx, cy, rTrack, Math.max(-180, prevDeg + 1.5), Math.min(0, nextDeg - 1.5)),
                fill: 'none',
                stroke: step.color,
                strokeWidth: isLit ? 9 : 7,
                strokeOpacity: isAuto ? 0.24 : (isLit ? 0.28 : 0.14),
                strokeLinecap: 'round',
              })
            }),
            // Continuous static gradient arc (full soft arc when auto, active slice when manual/dragging)
            !showManualNeedle
              ? h('path', {
                  className: 'dnb-fan-arc-active',
                  d: fanDescribeArc(cx, cy, rTrack, -180, 0),
                  fill: 'none',
                  stroke: `url(#${gradIdRef.current})`,
                  strokeWidth: 7.5,
                  strokeOpacity: 0.72,
                  strokeLinecap: 'round',
                })
              : (activeAngle > -179.4
                  ? h('path', {
                      className: 'dnb-fan-arc-active',
                      'data-dragging': dragging ? '1' : '0',
                      d: fanDescribeArc(cx, cy, rTrack, -180, activeAngle),
                      fill: 'none',
                      stroke: `url(#${gradIdRef.current})`,
                      strokeWidth: 8,
                      strokeLinecap: 'round',
                    })
                  : null),
            // Transparent interactive fan wedges for native title hover hints & click-to-snap
            FAN_EFFORT_STEPS.map((step, i) => {
              const wStart = i === 0 ? -180 : (FAN_EFFORT_STEPS[i - 1].deg + step.deg) / 2
              const wEnd = i === FAN_EFFORT_STEPS.length - 1 ? 0 : (step.deg + FAN_EFFORT_STEPS[i + 1].deg) / 2
              const opt = THINKING_EFFORT_OPTIONS.find(o => o.key === step.key) || {}
              return h(
                'path',
                {
                  key: 'hit-' + step.key,
                  d: fanDescribeWedge(cx, cy, 30, 96, wStart, wEnd),
                  fill: hoverKey === step.key ? step.color : 'transparent',
                  fillOpacity: hoverKey === step.key ? 0.09 : 0,
                  style: { cursor: dragging ? 'grabbing' : 'pointer' },
                  onMouseEnter: () => setHoverKey(step.key),
                  onMouseLeave: () => setHoverKey(prev => (prev === step.key ? '' : prev)),
                },
                h('title', null, `${opt.label || step.label}：${opt.hint || ''}`),
              )
            }),
            // Tick dots + outer labels
            FAN_EFFORT_STEPS.map(step => {
              const pt = fanPolarPoint(cx, cy, rTrack, step.deg)
              const lpt = fanPolarPoint(cx, cy, rTrack + 17, step.deg)
              const isCur = !isAuto && (dragging ? (previewStep && previewStep.key === step.key) : committedKey === step.key)
              const isHover = hoverKey === step.key
              return h(
                'g',
                { key: 'tick-' + step.key, style: { pointerEvents: 'none' } },
                h('circle', {
                  cx: pt.x,
                  cy: pt.y,
                  r: isCur || isHover ? 4.4 : 2.6,
                  fill: isCur || isHover ? step.color : 'var(--dnb-text-3)',
                  fillOpacity: isCur || isHover ? 1 : 0.65,
                  stroke: 'var(--dnb-popover)',
                  strokeWidth: isCur ? 1.5 : 0,
                }),
                h(
                  'text',
                  {
                    x: lpt.x,
                    y: lpt.y + 3,
                    textAnchor: step.deg <= -155 ? 'end' : (step.deg >= -25 ? 'start' : 'middle'),
                    fontSize: compact ? 10 : 10.5,
                    fontWeight: isCur || isHover ? 700 : 500,
                    fill: isCur || isHover ? step.color : 'var(--dnb-text-3)',
                  },
                  step.label,
                ),
              )
            }),
            // Static/snapping needle only when manual fixed notch or actively dragging (no auto sweep animation)
            showManualNeedle
              ? h(
                  'g',
                  { transform: `translate(${cx}, ${cy})`, style: { pointerEvents: 'none' } },
                  h(
                    'g',
                    {
                      className: 'dnb-fan-needle',
                      'data-dragging': dragging ? '1' : '0',
                      style: { transform: `rotate(${needleRotateDeg}deg)` },
                    },
                    h('line', {
                      x1: 0,
                      y1: 0,
                      x2: 0,
                      y2: -54,
                      stroke: previewStep ? previewStep.color : '#818cf8',
                      strokeWidth: 2.6,
                      strokeLinecap: 'round',
                    }),
                    h('circle', {
                      cx: 0,
                      cy: -54,
                      r: 3.2,
                      fill: '#ffffff',
                      stroke: previewStep ? previewStep.color : '#6366f1',
                      strokeWidth: 1.6,
                    }),
                  ),
                )
              : null,
            // Draggable thumb halo on the active track angle (when manual or dragging)
            showManualNeedle
              ? h('circle', {
                  cx: knobPt.x,
                  cy: knobPt.y,
                  r: dragging ? 7 : 5.5,
                  fill: previewStep ? previewStep.color : '#818cf8',
                  fillOpacity: 0.28,
                  style: { pointerEvents: 'none' },
                })
              : null,
          ),
          // Center Auto-Adjust Pivot Hub Button
          h('button', {
            type: 'button',
            className: 'dnb-fan-hub',
            'data-active': isAuto && !dragging ? '1' : '0',
            title: isAuto
              ? '当前已是「🪄 自动调节」：按任务复杂度自动切换参谋思考深度；拖住外圈弧线可手调挡位'
              : '点击切回「🪄 自动调节」，或继续拖住弧线手调挡位',
            onPointerDown: e => e.stopPropagation(),
            onMouseEnter: () => setHoverKey('auto'),
            onMouseLeave: () => setHoverKey(prev => (prev === 'auto' ? '' : prev)),
            onClick: e => {
              e.stopPropagation()
              commitKey('auto')
            },
          },
            h('span', { className: 'dnb-fan-hub-main' },
              dragging && previewStep
                ? previewStep.label
                : (isAuto ? bi('🪄 自动', '🪄 Auto') : (committedStep ? committedStep.label : bi('自动', 'Auto')))),
            h('span', { className: 'dnb-fan-hub-sub' },
              isAuto && !dragging ? bi('智能调节', 'Adaptive') : bi('点此自动', 'Set Auto')),
          ),
        ),
      )
    }

    /* ------------------------------------------- Shared Collapsible Accordion Card */

    /**
     * Unified collapsible accordion card shared across Chief, Tasks, Peers, Archives, and Boundaries tabs.
     * Left chevron points right (0deg) when collapsed and down (90deg) when open.
     */
    function AccCard({
      open = true,
      onToggle = null,
      title,
      icon = null,
      accentColor = '',
      preview = '',
      count = '',
      badges = null,
      headerExtra = null,
      actions = null,
      showPullHint = true,
      pullHintOpen = null,
      pullHintClosed = null,
      className = '',
      style = undefined,
      bodyStyle = undefined,
      headTitle = '',
      cardRef = null,
      children,
    }) {
      const openHintText = pullHintOpen !== null ? pullHintOpen : bi('收起 ▴', 'Collapse ▴')
      const closedHintText = pullHintClosed !== null ? pullHintClosed : bi('拉起 ▾', 'Expand ▾')
      const canToggle = typeof onToggle === 'function'
      const cardCls = ['dnb-acc-card', className].filter(Boolean).join(' ')
      const mergedStyle = accentColor
        ? { ...(style || {}), borderLeft: `3px solid ${accentColor}` }
        : style

      return h(
        'div',
        {
          ref: cardRef || undefined,
          className: cardCls,
          'data-open': open ? '1' : '0',
          style: mergedStyle,
        },
        h(
          'div',
          {
            className: 'dnb-acc-head',
            style: canToggle ? undefined : { cursor: 'default' },
            title: headTitle || (canToggle ? (open ? bi('点击收起', 'Click to collapse') : bi('点击拉起', 'Click to expand')) : undefined),
            onClick: canToggle ? onToggle : undefined,
          },
          h(
            'div',
            { className: 'dnb-acc-title-wrap' },
            canToggle
              ? h(Icon, { name: 'chevron', size: 12.5, className: 'dnb-acc-chevron' })
              : null,
            icon || null,
            title ? h('span', { className: 'dnb-acc-title' }, title) : null,
            badges || null,
            headerExtra || null,
            count !== '' && count !== null && count !== undefined
              ? h('span', { className: 'dnb-acc-count' }, String(count))
              : null,
            !open && preview
              ? h('span', { className: 'dnb-acc-preview', title: typeof preview === 'string' ? preview : undefined }, preview)
              : null,
          ),
          (actions || (canToggle && showPullHint))
            ? h(
                'div',
                { className: 'dnb-acc-ops', onClick: e => e.stopPropagation() },
                actions || null,
                canToggle && showPullHint
                  ? h('span', { className: 'dnb-acc-pull-hint', onClick: onToggle }, open ? openHintText : closedHintText)
                  : null,
              )
            : null,
        ),
        open
          ? h('div', { className: 'dnb-acc-body', style: bodyStyle }, children)
          : null,
      )
    }

    // === [module: src/client/components/modals.js] ===
    /**
     * components/modals.js
     *
     * Popovers, SuggestionBanner, and all safety/risk/approval/elevation/audit confirmation modals.
     */


    function ModelPickerPopover({ view }) {
      if (!view.secModelMenuOpen) return null
      const catalog = view.secModelsCatalog || (view.secView && view.secView.models) || null
      const currentRef = (view.chiefMeta && view.chiefMeta.modelRef) || ''
      const followRef = (catalog && (catalog.followRef || catalog.defaultRef))
        || (view.chiefMeta && view.chiefMeta.followModelRef)
        || ''
      const followProvider = followRef.includes('/') ? followRef.split('/')[0] : ''
      const followSubtitle = (catalog && catalog.followLabel) || fullModelWithChannel(followRef, catalog)

      const providers = []
      if (catalog && Array.isArray(catalog.providers) && catalog.providers.length) {
        providers.push(...catalog.providers)
      } else if (catalog && Array.isArray(catalog.models)) {
        const byProv = new Map()
        for (const item of catalog.models) {
          if (!item || !item.ref) continue
          const pid = item.provider || item.ref.split('/')[0] || 'default'
          if (!byProv.has(pid)) {
            byProv.set(pid, { id: pid, label: item.providerName || pid, needsKey: Boolean(item.needsKey), models: [] })
          }
          const group = byProv.get(pid)
          if (!item.needsKey) group.needsKey = false
          group.models.push({
            ref: item.ref,
            id: item.id || item.ref,
            label: item.name || item.label || item.id || item.ref,
            isCurrentLead: Boolean(item.isCurrentLead) || item.ref === followRef,
            needsKey: Boolean(item.needsKey),
          })
        }
        providers.push(...byProv.values())
        // Float the main conversation's active provider to the very top, sink unkeyed providers to the bottom
        providers.sort((a, b) => {
          const aLead = a.id === followProvider ? 1 : 0
          const bLead = b.id === followProvider ? 1 : 0
          if (aLead !== bLead) return bLead - aLead
          const aUnkeyed = a.needsKey ? 1 : 0
          const bUnkeyed = b.needsKey ? 1 : 0
          return aUnkeyed - bUnkeyed
        })
      }

      return h(
        React.Fragment,
        null,
        h('div', {
          style: { position: 'fixed', inset: 0, zIndex: 9998 },
          onClick: () => patch({ secModelMenuOpen: false }),
        }),
        h(
          'div',
          {
            className: 'dnb-menu',
            style: {
              position: 'absolute',
              top: 42,
              right: 12,
              minWidth: 262,
              maxWidth: 316,
              maxHeight: 'min(76vh, 480px)',
              overflowY: 'auto',
              zIndex: 9999,
            },
          },
          h('div', { style: { padding: '6px 10px 8px', borderBottom: '1px solid var(--dnb-border)', marginBottom: 4 } },
            h('div', { style: { fontSize: 10.5, fontWeight: 700, color: 'var(--dnb-text-3)', marginBottom: 4 } },
              bi('🧠 参谋长思考强度（拖住弧线调挡 · 点中心自动）', '🧠 Chief Reasoning Effort (drag arc · tap center for Auto)')),
            h(EffortFanGauge, {
              compact: true,
              value: (view.chiefMeta && view.chiefMeta.thinkingEffort) || 'auto',
              onChange: nextKey => void updateSecConfig({ thinkingEffort: nextKey }),
            }),
          ),
          h('div', { style: { padding: '5px 10px 4px', fontSize: 10.5, fontWeight: 600, color: 'var(--dnb-text-3)' } },
            bi('选择参谋长专职模型', 'Select Dedicated Chief Model')),
          h(
            'div',
            {
              className: 'dnb-menu-item',
              style: { justifyContent: 'space-between', gap: 8, fontWeight: !currentRef ? 600 : 400, color: !currentRef ? 'var(--dnb-accent)' : undefined },
              onClick: () => {
                patch({ secModelMenuOpen: false })
                void updateSecConfig({ modelRef: '' })
              },
            },
            h('div', { style: { minWidth: 0, flex: 1 } },
              h('div', null, bi('✦ 自动跟随主对话模型', '✦ Auto-follow Lead Model')),
              followSubtitle
                ? h('div', {
                    style: { fontSize: 10.5, color: 'var(--dnb-text-3)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' },
                    title: followRef,
                  }, followSubtitle)
                : null,
            ),
            !currentRef ? h(Icon, { name: 'check', size: 13 }) : null,
          ),
          providers.map(prov =>
            h(
              'div',
              { key: prov.id, style: { marginTop: 4, paddingTop: 4, borderTop: '1px solid var(--dnb-border)', opacity: prov.needsKey ? 0.6 : 1 } },
              h(
                'div',
                { style: { padding: '3px 10px', fontSize: 10.5, color: 'var(--dnb-text-3)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6 } },
                h('span', null, prov.label || prov.id),
                prov.id === followProvider
                  ? h('span', { style: { fontSize: 9.5, color: 'var(--dnb-accent)', fontWeight: 600 } }, '主对话渠道')
                  : (prov.needsKey ? h('span', { style: { fontSize: 9.5 } }, '未配密钥') : null),
              ),
              (prov.models || []).map(mod => {
                const active = currentRef === mod.ref
                return h(
                  'div',
                  {
                    key: mod.ref,
                    className: 'dnb-menu-item',
                    title: mod.ref,
                    style: { justifyContent: 'space-between', gap: 6, fontWeight: active ? 600 : 400, color: active ? 'var(--dnb-accent)' : undefined },
                    onClick: () => {
                      patch({ secModelMenuOpen: false })
                      void updateSecConfig({ modelRef: mod.ref })
                    },
                  },
                  h('span', { style: { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', flex: 1 } }, mod.label || mod.id),
                  mod.isCurrentLead
                    ? h('span', {
                        style: {
                          fontSize: 9.5,
                          padding: '1px 5px',
                          borderRadius: 99,
                          background: 'rgba(10,132,255,0.14)',
                          color: 'var(--dnb-accent)',
                          flexShrink: 0,
                        },
                      }, '主对话')
                    : null,
                  active ? h(Icon, { name: 'check', size: 13 }) : null,
                )
              }),
            ),
          ),
          !providers.length
            ? h('div', { style: { padding: '8px 10px', fontSize: 11, color: 'var(--dnb-text-3)' } },
                catalog ? bi('未检测到额外模型提供商，将自动跟随主对话模型。', 'No extra providers found; following lead model.') : bi('加载模型列表中…', 'Loading models…'))
            : null,
          h(
            'div',
            { className: 'dnb-lang-inline-bar', onClick: e => e.stopPropagation() },
            h('span', { style: { fontSize: 10.5, color: 'var(--dnb-text-3)', fontWeight: 600 } }, bi('🌐 语言', '🌐 Lang')),
            h(
              'div',
              { className: 'dnb-seg', style: { padding: 1.5, flex: '0 0 auto' } },
              [
                { key: 'auto', label: bi('自动', 'Auto') },
                { key: 'zh', label: '中文' },
                { key: 'en', label: 'EN' },
              ].map(opt =>
                h('button', {
                  key: opt.key,
                  type: 'button',
                  className: 'dnb-seg-btn',
                  style: { padding: '2px 7px', fontSize: 10 },
                  'data-active': (view.uiLangPref || getUiLangPref()) === opt.key ? '1' : '0',
                  onClick: () => void updateSecConfig({ uiLang: opt.key }),
                }, opt.label),
              ),
            ),
          ),
        ),
      )
    }

    function PacePickerPopover({ view }) {
      if (!view.secPaceMenuOpen) return null
      const meta = view.chiefMeta || {}
      const currentRunMode = meta.stopped
        ? 'off'
        : (meta.runMode || (meta.paceMode === 'auto' ? 'managed' : (meta.paceMode === 'smart' ? 'patrol' : 'off')))
      return h(
        React.Fragment,
        null,
        h('div', {
          style: { position: 'fixed', inset: 0, zIndex: 9998 },
          onClick: () => patch({ secPaceMenuOpen: false }),
        }),
        h(
          'div',
          {
            className: 'dnb-menu',
            style: {
              position: 'absolute',
              top: 42,
              right: 12,
              width: 280,
              zIndex: 9999,
            },
          },
          h('div', { style: { padding: '5px 10px 4px', fontSize: 10.5, fontWeight: 600, color: 'var(--dnb-text-3)' } },
            bi('参谋长三态运行模式（与战术正交）', 'Chief Run Mode (orthogonal to tactics)')),
          RUN_MODE_OPTIONS.map(opt => {
            const rm = runModeMeta(opt.key)
            const active = currentRunMode === opt.key
            return h(
              'div',
              {
                key: opt.key,
                className: 'dnb-menu-item',
                style: {
                  alignItems: 'flex-start',
                  justifyContent: 'space-between',
                  gap: 8,
                  padding: '7px 10px',
                  color: active ? 'var(--dnb-accent)' : undefined,
                },
                onClick: () => {
                  if (opt.key === 'managed' && currentRunMode !== 'managed') {
                    patch({ secPaceMenuOpen: false, autoPilotConfirmOpen: true })
                    return
                  }
                  patch({ secPaceMenuOpen: false })
                  void updateSecConfig({
                    runMode: opt.key,
                    ...(opt.key === 'off' ? { paceMode: 'manual', autoPilot: false } : {}),
                  })
                },
              },
              h('div', { style: { minWidth: 0, flex: 1 } },
                h('div', { style: { fontSize: 12, fontWeight: active ? 600 : 500, marginBottom: 2 } }, rm.label || opt.label),
                h('div', { style: { fontSize: 10.5, lineHeight: 1.4, color: 'var(--dnb-text-3)', whiteSpace: 'normal' } }, rm.hint || opt.hint),
              ),
              active ? h(Icon, { name: 'check', size: 13, style: { marginTop: 2 } }) : null,
            )
          }),
        ),
      )
    }

    function describeSuggestionMeta(sug) {
      if (!sug) return { typeLabel: '参谋建议', impact: '协同调整', expect: '按建议推进', tone: 'var(--dnb-accent)', bg: 'rgba(10, 132, 255, 0.12)' }
      if (sug.kind === 'archive_op') {
        return {
          typeLabel: '📌 档案注入/桌面建议',
          impact: `影响：${sug.targetLabel || '📌 认知桌面'}（不越级改动冷库）`,
          expect: '预期：确认后执行桌面置顶/撤回或一次性递送主对话',
          tone: '#f59e0b',
          bg: 'rgba(245, 158, 11, 0.13)',
        }
      }
      if (sug.kind === 'model_effort') {
        return {
          typeLabel: '🧠 模型思考调挡建议',
          impact: `影响：调整 ${sug.targetLabel || '@lead'} 思考深度`,
          expect: '预期：按建议实时热切换下一轮模型推理深度',
          tone: '#a5b4fc',
          bg: 'rgba(99, 102, 241, 0.16)',
        }
      }
      if (sug.kind === 'goal_approval') {
        return {
          typeLabel: '🎯 目标结项请示',
          impact: '影响：锁定/完结当前主目标与验收状态',
          expect: '预期：核心目标标为达成并停止继续催跑',
          tone: '#30d158',
          bg: 'rgba(48, 209, 88, 0.12)',
        }
      }
      if (sug.kind === 'guard_wall') {
        return {
          typeLabel: '🧱 物理驻墙提案',
          impact: `影响：${sug.targetLabel || '🌐 全局随身驻墙'}（事前物理硬拦截）`,
          expect: '预期：确认后写入 guard-walls.json，所有代理触线即刻物理阻断',
          tone: '#f87171',
          bg: 'rgba(239, 68, 68, 0.13)',
        }
      }
      if (sug.kind === 'wall_removal') {
        const spec = (sug.wallRemovalSpec && typeof sug.wallRemovalSpec === 'object') ? sug.wallRemovalSpec : {}
        const actText = spec.action === 'remove' ? '永久移除该物理驻墙' : '暂挂休眠该物理驻墙'
        return {
          typeLabel: '⚠️ 参谋请示拆墙（需人工批准）',
          impact: `影响：${spec.wallTitle || sug.targetLabel || '目标物理驻墙'}（L0–L3 均须人类审批）`,
          expect: `预期：批准后${actText}，参谋绝无权越权自拆`,
          tone: '#ef4444',
          bg: 'rgba(239, 68, 68, 0.18)',
        }
      }
      if (sug.kind === 'bound') {
        const colLabel = sug.boundField === 'allowed' ? '必做事项' : (sug.boundField === 'notes' ? '注意事项' : '禁止红线')
        const repCount = Array.isArray(sug.replaces) ? sug.replaces.filter(Boolean).length : 0
        return {
          typeLabel: repCount > 0 ? `🏛 边界浓缩 (${repCount} 合 1)` : `🏛 ${colLabel}请示`,
          impact: sug.pinGlobal ? '影响：📌 全局定住边界（跨所有任务生效）' : '影响：本任务会话工作边界（实时生效）',
          expect: repCount > 0 ? `预期：替换并清理 ${repCount} 条零散旧边界` : `预期：写入${colLabel}并广播全体代理遵照执行`,
          tone: '#fbbf24',
          bg: 'rgba(245, 158, 11, 0.12)',
        }
      }
      if (sug.kind === 'advice') {
        return {
          typeLabel: '💡 参谋长主动建议',
          impact: `影响：向 @${shortAgentName(sug.targetLabel || sug.target || '主对话')} 递交协同建议`,
          expect: '预期：按建议纠偏方向或补全缺失验证步骤',
          tone: 'var(--dnb-accent)',
          bg: 'rgba(10, 132, 255, 0.12)',
        }
      }
      return {
        typeLabel: '✦ 参谋协同建议',
        impact: `影响：向 @${shortAgentName(sug.targetLabel || sug.target || '主对话')} 发送${sug.mode === 'steer' ? '实时插话' : '顺延指令'}`,
        expect: '预期：按拟定草案执行下一步动作并同步看板',
        tone: 'var(--dnb-accent)',
        bg: 'rgba(10, 132, 255, 0.10)',
      }
    }

    function SuggestionBanner({ view }) {
      const rawSuggestions = (view.secView && Array.isArray(view.secView.suggestions))
        ? view.secView.suggestions.filter(s => s && s.status === 'pending')
        : []
      const rankSug = s => ((s.kind === 'goal_approval' || s.kind === 'wall_removal') ? 0 : (s.kind === 'bound' || s.kind === 'guard_wall') ? 1 : 2)
      const suggestions = [...rawSuggestions].sort((a, b) => rankSug(a) - rankSug(b))
      const [expandedId, setExpandedId] = React.useState('')
      const [unselectedIds, setUnselectedIds] = React.useState({})

      if (!suggestions.length) return null

      const selectedList = suggestions.filter(s => !unselectedIds[s.id])
      const selectedGoalCount = selectedList.filter(s => s.kind === 'goal_approval').length
      const selectedNonGoalCount = selectedList.length - selectedGoalCount
      const canExecuteCount = selectedList.length

      const toggleSelect = (id) => {
        setUnselectedIds(prev => {
          const next = { ...prev }
          if (next[id]) delete next[id]
          else next[id] = true
          return next
        })
      }

      return h(
        'div',
        { className: 'dnb-sug-group' },
        // Unified single top action bar
        h(
          'div',
          { className: 'dnb-sug-top' },
          h(
            'div',
            { style: { display: 'flex', alignItems: 'center', gap: 6, minWidth: 0, flexWrap: 'wrap' } },
            h('span', { style: { fontSize: 12, fontWeight: 700, color: 'var(--dnb-text)' } },
              `💡 参谋长建议 (${suggestions.length})`),
            h('span', { style: { fontSize: 10.5, color: 'var(--dnb-text-3)' } },
              `已勾选 ${canExecuteCount}/${suggestions.length} 项 · 统一执行并产出回执`),
          ),
          h(
            'div',
            { style: { display: 'flex', alignItems: 'center', gap: 6, flexShrink: 0 } },
            h('button', {
              type: 'button',
              className: 'dnb-pill',
              style: { height: 26, padding: '0 9px', fontSize: 11, color: 'var(--dnb-text-3)' },
              disabled: Boolean(view.secBusy),
              title: '忽略当前全部待处理建议',
              onClick: () => void dismissPendingSuggestions(suggestions),
            }, '全部忽略'),
            h('button', {
              type: 'button',
              className: 'dnb-primary-btn',
              style: { height: 26, padding: '0 12px', fontSize: 11.5, fontWeight: 700 },
              disabled: Boolean(view.secBusy) || canExecuteCount === 0,
              title: selectedGoalCount > 0 && selectedNonGoalCount > 0
                ? '在当前权限与红线范围内批量执行所选建议（含目标结项请示）并统一汇报回执'
                : '在当前权限与红线范围内统一执行所选建议并输出执行回执',
              onClick: () => void executePendingSuggestions({
                ids: selectedList.map(s => s.id),
                includeGoalApproval: selectedGoalCount > 0,
              }),
            }, view.secBusy ? '执行中…' : `▶ 执行建议 (${canExecuteCount})`),
          ),
        ),

        // Read-only informative suggestion items (NO per-item execute buttons)
        suggestions.slice(0, 6).map(sug => {
          const meta = describeSuggestionMeta(sug)
          const isChecked = !unselectedIds[sug.id]
          const openDraft = expandedId === sug.id
          const replacesList = Array.isArray(sug.replaces) ? sug.replaces.filter(Boolean) : []
          const statusLabel = sug.status === 'applied' ? '已执行' : (sug.status === 'dismissed' ? '已忽略' : '待执行')

          return h(
            'div',
            {
              key: sug.id,
              className: 'dnb-sug-card',
              style: {
                borderColor: isChecked ? undefined : 'var(--dnb-border)',
                opacity: isChecked ? 1 : 0.72,
              },
            },
            h(
              'div',
              { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6, marginBottom: 4 } },
              h(
                'label',
                { style: { display: 'flex', alignItems: 'center', gap: 6, minWidth: 0, cursor: 'pointer', flex: 1 } },
                h('input', {
                  type: 'checkbox',
                  checked: isChecked,
                  onChange: () => toggleSelect(sug.id),
                }),
                h('span', {
                  className: 'dnb-tag',
                  style: { color: meta.tone, background: meta.bg, fontSize: 10.5, fontWeight: 700 },
                }, meta.typeLabel),
                sug.targetLabel
                  ? h('span', { className: 'dnb-tag', style: { fontSize: 10.5 } }, '@' + shortAgentName(sug.targetLabel, true))
                  : null,
                h('span', { className: 'dnb-tag', style: { fontSize: 10, color: 'var(--dnb-text-2)' } }, statusLabel),
              ),
              h(
                'div',
                { style: { display: 'flex', alignItems: 'center', gap: 4, flexShrink: 0 } },
                sug.draftText
                  ? h('button', {
                      type: 'button',
                      className: 'dnb-mini-btn',
                      onClick: () => setExpandedId(openDraft ? '' : sug.id),
                    }, openDraft ? '收起内容' : '详情')
                  : null,
                h('button', {
                  type: 'button',
                  className: 'dnb-icon-btn',
                  style: { width: 20, height: 20 },
                  title: '忽略此条建议',
                  onClick: () => void decideSuggestion(sug, 'dismiss'),
                }, h(Icon, { name: 'x', size: 12 })),
              ),
            ),
            h('div', { style: { fontSize: 12.2, fontWeight: 600, color: 'var(--dnb-text)', lineHeight: 1.45, marginBottom: 3 } }, sug.title),
            sug.reason
              ? h('div', { style: { fontSize: 11.2, color: 'var(--dnb-text-2)', lineHeight: 1.45, marginBottom: 4 } },
                  '原因：' + sug.reason)
              : null,
            h(
              'div',
              { className: 'dnb-sug-meta-row' },
              h('span', { className: 'dnb-tag', style: { fontSize: 10.5 } }, meta.impact),
              h('span', { className: 'dnb-tag', style: { fontSize: 10.5 } }, meta.expect),
            ),
            replacesList.length > 0
              ? h('div', { style: { fontSize: 10.5, color: 'var(--dnb-text-3)', marginTop: 4 } },
                  `整合替代 ${replacesList.length} 条旧规：` + replacesList.slice(0, 3).map(r => '「' + clampTitle(r, 14) + '」').join('、'))
              : null,
            openDraft && sug.draftText
              ? h('div', {
                  style: {
                    padding: '6px 9px',
                    marginTop: 6,
                    borderRadius: 8,
                    background: 'var(--dnb-card)',
                    border: '1px solid var(--dnb-border)',
                    fontSize: 11.5,
                    color: 'var(--dnb-text-2)',
                    whiteSpace: 'pre-wrap',
                  },
                }, renderStructuredText(sug.draftText))
              : null,
          )
        }),
      )
    }

    const MODAL_WALL_TYPE_TAG = {
      forbid_cmd: '🚫 禁跑命令',
      forbid_path: '🚧 禁碰路径',
      restrict_write: '🔐 仅限目录可写',
      require_approval_cmd: '🛡️ 高危命令先请示',
      deny_tool: '⛔ 禁用工具',
    }

    function InterventionConfirmModal({ view, board }) {
      const meta = view.chiefMeta || {}
      const tm = meta.tacticalModes || {}
      const rawBounds = (board && board.bounds) || (view.board && view.board.bounds) || {}
      const savedBoardObj = (board && board.objective) ? String(board.objective).trim() : ''
      const forbiddenList = (Array.isArray(rawBounds.forbidden) ? rawBounds.forbidden : [])
        .map(f => (typeof f === 'string' ? f.trim() : String((f && f.text) || '').trim()))
        .filter(Boolean)
      const allWalls = Array.isArray(view.guardWalls) ? view.guardWalls : []
      const activeWalls = allWalls.filter(w => w && w.scope !== 'paused' && w.activeNow !== false)
      const pausedWallsCount = allWalls.filter(w => w && w.scope === 'paused').length

      const [objDraft, setObjDraft] = React.useState(savedBoardObj)
      const [objLocked, setObjLocked] = React.useState(false)
      const [objFlashRed, setObjFlashRed] = React.useState(false)
      const [objGuardHint, setObjGuardHint] = React.useState('')
      const [suggestBusy, setSuggestBusy] = React.useState(false)
      const [suggestHistory, setSuggestHistory] = React.useState([])
      const [lastAiText, setLastAiText] = React.useState('')
      const [lastWasAiGuess, setLastWasAiGuess] = React.useState(false)
      const [suggestRationale, setSuggestRationale] = React.useState('')
      const [confirmBusy, setConfirmBusy] = React.useState(false)
      const [wallsSecCollapsed, setWallsSecCollapsed] = React.useState(false)
      const [redlinesSecCollapsed, setRedlinesSecCollapsed] = React.useState(false)
      const objBoxRef = React.useRef(null)

      React.useEffect(() => {
        if (!view.interventionModalOpen) return
        setObjDraft(savedBoardObj)
        setObjLocked(false)
        setObjFlashRed(false)
        setObjGuardHint('')
        setSuggestBusy(false)
        setSuggestHistory([])
        setLastAiText('')
        setLastWasAiGuess(false)
        setSuggestRationale('')
        setConfirmBusy(false)
        setWallsSecCollapsed(false)
        setRedlinesSecCollapsed(false)
      }, [view.interventionModalOpen])

      if (!view.interventionModalOpen) return null
      const permMode = ['advisor', 'assistant', 'strategist', 'chief'].includes(meta.permissionMode) ? meta.permissionMode : 'advisor'
      const trimmedDraft = String(objDraft || '').trim()
      const triggerObjRedFlash = (hintMsg) => {
        setObjGuardHint(hintMsg || '请先明确核心总目标并点击右上角「🔒 锁定」，再开启强介入！')
        setObjFlashRed(false)
        const fire = () => setObjFlashRed(true)
        if (typeof requestAnimationFrame === 'function') requestAnimationFrame(fire)
        else setTimeout(fire, 16)
        try {
          if (objBoxRef.current && typeof objBoxRef.current.scrollIntoView === 'function') {
            objBoxRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' })
          }
        } catch {}
      }
      const noDefenseRules = activeWalls.length === 0 && forbiddenList.length === 0
      const allDefenseCollapsed = wallsSecCollapsed && redlinesSecCollapsed
      const toggleAllDefense = () => {
        const next = !allDefenseCollapsed
        setWallsSecCollapsed(next)
        setRedlinesSecCollapsed(next)
      }

      const handleSuggestObjective = async () => {
        if (suggestBusy) return
        if (objLocked) {
          patch({ notice: '当前核心目标输入框已锁定，请先点击「解锁」后再点建议或微调' })
          return
        }
        const curText = String(objDraft || '').trim()
        const shouldGuess = !curText || (lastWasAiGuess && lastAiText && curText === lastAiText.trim())
        const nextMode = shouldGuess ? 'guess' : 'refine'
        setSuggestBusy(true)
        try {
          const out = await call('chief/suggest-objective', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({
              session: view.sessionId,
              draft: curText,
              mode: nextMode,
              previousSuggestions: suggestHistory,
            }),
          })
          if (out && out.suggestion) {
            const nextText = String(out.suggestion).trim()
            setObjDraft(nextText)
            setLastAiText(nextText)
            setLastWasAiGuess(nextMode === 'guess')
            setSuggestHistory(prev => prev.concat(nextText).slice(-12))
            setSuggestRationale(String(out.rationale || ''))
          }
        } catch (error) {
          patch({ error: String((error && error.message) || error) })
        } finally {
          setSuggestBusy(false)
        }
      }

      return h(
        'div',
        {
          className: 'dnb-modal-backdrop',
          onClick: e => {
            if (e.target === e.currentTarget && !confirmBusy) patch({ interventionModalOpen: false })
          },
        },
        h(
          'div',
          { className: 'dnb-modal-card', style: { maxHeight: '86vh', overflowY: 'auto' } },
          h(
            'div',
            { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 } },
            h('span', { style: { fontSize: 13.5, fontWeight: 700, color: '#f59e0b' } }, '⚡ 启用「主动强介入」— 设定核心目标与风险核对'),
            h('button', {
              type: 'button',
              className: 'dnb-icon-btn',
              style: { width: 22, height: 22 },
              disabled: confirmBusy,
              onClick: () => patch({ interventionModalOpen: false }),
            }, h(Icon, { name: 'x', size: 13 })),
          ),
          // Core Objective Destination Editor inside Modal (建议 + 必须先点选锁定)
          h(
            'div',
            {
              ref: objBoxRef,
              className: objFlashRed ? 'dnb-obj-flash-red' : undefined,
              style: {
                borderRadius: 9,
                padding: '9px 10px',
                border: objLocked
                  ? '1px solid rgba(245, 158, 11, 0.58)'
                  : '1.5px solid rgba(255, 69, 58, 0.62)',
                background: objLocked ? 'rgba(245, 158, 11, 0.08)' : 'rgba(255, 69, 58, 0.06)',
                display: 'flex',
                flexDirection: 'column',
                gap: 6,
                fontSize: 11.5,
              },
            },
            h(
              'div',
              { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6, flexWrap: 'wrap' } },
              h('span', { style: { fontWeight: 700, color: objLocked ? 'var(--dnb-text)' : '#ff6961' } },
                objLocked
                  ? '🎯 强介入核心总目标（已锁定 · 开启后立即推进）'
                  : '🎯 强介入核心总目标（须先点右侧「锁定目标」才可开启）'),
              h(
                'div',
                { style: { display: 'flex', alignItems: 'center', gap: 5 } },
                h('button', {
                  type: 'button',
                  className: 'dnb-mini-btn',
                  'data-tone': 'blue',
                  disabled: suggestBusy || objLocked,
                  title: trimmedDraft && !(lastWasAiGuess && trimmedDraft === lastAiText.trim())
                    ? '在您输入框已有文字的基础上由参谋长微调润色'
                    : '由参谋长结合对话现状自动猜测建议（可反复点击继续换角度猜意图）',
                  onClick: () => void handleSuggestObjective(),
                }, suggestBusy
                  ? '推演中…'
                  : (trimmedDraft && !(lastWasAiGuess && trimmedDraft === lastAiText.trim()) ? '✦ 微调建议' : '✦ 建议')),
                h('button', {
                  type: 'button',
                  className: 'dnb-mini-btn',
                  'data-tone': objLocked ? 'amber' : 'red',
                  title: objLocked ? '点击解锁以继续编辑或点建议' : '点击锁定明确后的核心总目标，解锁“开启强介入”开关',
                  onClick: () => {
                    if (!objLocked && !trimmedDraft) {
                      triggerObjRedFlash('请先填写明确的核心总目标，再点选「锁定目标」！')
                      return
                    }
                    setObjLocked(v => {
                      const nextLocked = !v
                      if (nextLocked) {
                        setObjFlashRed(false)
                        setObjGuardHint('')
                      }
                      return nextLocked
                    })
                  },
                }, objLocked ? '🔒 已锁定目标' : '🔓 锁定目标'),
              ),
            ),
            h('textarea', {
              className: 'dnb-input',
              rows: 3,
              readOnly: objLocked,
              placeholder: '输入核心目标，或留空直接点右上「✦ 建议」让参谋长为您揣摩填写（可反复点建议）…',
              style: {
                width: '100%',
                minHeight: 62,
                padding: '7px 9px',
                borderRadius: 7,
                fontSize: 12,
                lineHeight: 1.45,
                resize: 'vertical',
                borderColor: !objLocked ? 'rgba(255, 69, 58, 0.52)' : undefined,
                opacity: objLocked ? 0.88 : 1,
                cursor: objLocked ? 'not-allowed' : 'text',
              },
              value: objDraft,
              onChange: e => {
                if (objLocked) return
                setObjDraft(e.target.value)
                setLastWasAiGuess(false)
                if (objFlashRed) setObjFlashRed(false)
                if (objGuardHint) setObjGuardHint('')
              },
            }),
            suggestRationale
              ? h('div', { style: { fontSize: 11, color: '#60a5fa', lineHeight: 1.4 } }, '💡 参谋长思路：' + suggestRationale)
              : null,
            h('div', { style: { fontSize: 11, color: 'var(--dnb-text-3)', lineHeight: 1.4 } },
              !trimmedDraft
                ? h('span', { style: { color: '#ff6961', fontWeight: 600 } }, objGuardHint || '⚠ 请先明确核心总目标（可自行填写或点「✦ 建议」），再点击「锁定目标」。')
                : (!objLocked
                    ? h('span', { style: { color: '#ff6961', fontWeight: 600 } }, objGuardHint || '⚠ 尚差一步：请点击右上「🔓 锁定目标」确认锁定后，方可开启强介入（开启后将立即开始推进）。')
                    : '✓ 核心总目标已锁定：点击下方开启强介入后，将直接锁定本目标并立即开始推进，无需再发“继续”。')),
          ),
          // Live Boundaries & Guard Walls Readback (Physical Guard Walls + Forbidden Redlines)
          h(
            'div',
            {
              style: {
                borderRadius: 9,
                padding: '8px 10px',
                border: noDefenseRules ? '1px solid rgba(255, 69, 58, 0.48)' : '1px solid var(--dnb-border)',
                background: noDefenseRules ? 'rgba(255, 69, 58, 0.08)' : 'var(--dnb-card)',
                display: 'flex',
                flexDirection: 'column',
                gap: 6,
                fontSize: 11.5,
              },
            },
            h(
              'div',
              { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6, flexWrap: 'wrap' } },
              h(
                'div',
                { style: { display: 'flex', alignItems: 'center', gap: 5, flexWrap: 'wrap', minWidth: 0 } },
                h('strong', null, '🛡️ 已设防线核对：'),
                noDefenseRules
                  ? h('span', { style: { color: '#ff453a', fontWeight: 600 } }, '未设物理驻墙与禁止红线（强介入风险较高）')
                  : h(
                      React.Fragment,
                      null,
                      h('span', { style: { color: activeWalls.length > 0 ? '#f87171' : 'var(--dnb-text-3)', fontWeight: 700 } },
                        `🧱 物理驻墙 ${activeWalls.length} 堵`),
                      h('span', { style: { color: 'var(--dnb-text-3)' } }, '·'),
                      h('span', { style: { color: forbiddenList.length > 0 ? '#34d399' : 'var(--dnb-text-3)', fontWeight: 700 } },
                        `🚫 禁止红线 ${forbiddenList.length} 条`),
                    ),
              ),
              h(
                'div',
                { style: { display: 'inline-flex', alignItems: 'center', gap: 5, flexShrink: 0 } },
                !noDefenseRules
                  ? h('button', {
                      type: 'button',
                      className: 'dnb-mini-btn',
                      title: allDefenseCollapsed ? '一键拉开物理驻墙与禁止红线详情' : '一键收起物理驻墙与禁止红线详情',
                      onClick: toggleAllDefense,
                    }, allDefenseCollapsed ? '↕ 一键拉开' : '↕ 一键收起')
                  : null,
                h('button', {
                  type: 'button',
                  className: 'dnb-mini-btn',
                  'data-tone': noDefenseRules ? 'amber' : 'blue',
                  onClick: () => patch({ interventionModalOpen: false, tab: 'boundaries', settingsOpen: false }),
                }, '管理边界'),
              ),
            ),
            // Sub-section 1: Physical Guard Walls
            h(
              'div',
              {
                style: {
                  borderRadius: 7,
                  border: '1px solid rgba(248, 113, 113, 0.28)',
                  background: 'rgba(239, 68, 68, 0.05)',
                  overflow: 'hidden',
                },
              },
              h(
                'div',
                {
                  style: {
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 6,
                    padding: '5px 8px',
                    cursor: 'pointer',
                    userSelect: 'none',
                  },
                  onClick: () => setWallsSecCollapsed(v => !v),
                },
                h('span', { style: { fontSize: 11, fontWeight: 700, color: '#f87171' } },
                  `🧱 物理驻墙（事前硬拦截 · 已生效 ${activeWalls.length} 堵${pausedWallsCount > 0 ? ` · ${pausedWallsCount} 暂挂` : ''}）`),
                h(Icon, {
                  name: 'chevron',
                  size: 12,
                  style: {
                    color: 'var(--dnb-text-3)',
                    transform: wallsSecCollapsed ? 'none' : 'rotate(90deg)',
                    transition: 'transform 0.16s ease',
                  },
                }),
              ),
              !wallsSecCollapsed
                ? h(
                    'div',
                    { style: { padding: '0 8px 6px', display: 'flex', flexDirection: 'column', gap: 3.5 } },
                    activeWalls.length > 0
                      ? [
                          ...activeWalls.slice(0, 4).map(w => {
                            const scopeTag = w.scope === 'workspace' ? '📁本工程' : '🌐全局'
                            const typeTag = MODAL_WALL_TYPE_TAG[w.ruleType] || w.ruleType
                            const patStr = Array.isArray(w.patterns) ? w.patterns.join(', ') : ''
                            const previewPat = patStr.length > 52 ? patStr.slice(0, 52) + '…' : patStr
                            return h(
                              'div',
                              { key: w.id, style: { fontSize: 11, color: 'var(--dnb-text-2)', lineHeight: 1.45, wordBreak: 'break-word' } },
                              h('span', { style: { color: '#fca5a5', fontWeight: 600 } }, `• [${scopeTag} · ${typeTag}] `),
                              h('span', { style: { color: 'var(--dnb-text)', fontWeight: 600 } }, w.title || ''),
                              previewPat
                                ? h('span', { style: { color: 'var(--dnb-text-3)', fontFamily: 'ui-monospace, Menlo, Consolas, monospace', fontSize: 10.5 } }, ` — ${previewPat}`)
                                : null,
                            )
                          }),
                          activeWalls.length > 4
                            ? h('div', { key: 'more-walls', style: { fontSize: 10.5, color: 'var(--dnb-text-3)' } },
                                `…另有 ${activeWalls.length - 4} 堵物理驻墙共同生效中`)
                            : null,
                        ]
                      : h('div', { style: { fontSize: 10.5, color: 'var(--dnb-text-3)' } },
                          '暂未启用物理驻墙（可点右上「管理边界」手搓或手动驻防）'),
                  )
                : null,
            ),
            // Sub-section 2: Forbidden Redlines
            h(
              'div',
              {
                style: {
                  borderRadius: 7,
                  border: '1px solid var(--dnb-border)',
                  background: 'rgba(148, 163, 184, 0.05)',
                  overflow: 'hidden',
                },
              },
              h(
                'div',
                {
                  style: {
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 6,
                    padding: '5px 8px',
                    cursor: 'pointer',
                    userSelect: 'none',
                  },
                  onClick: () => setRedlinesSecCollapsed(v => !v),
                },
                h('span', { style: { fontSize: 11, fontWeight: 700, color: forbiddenList.length > 0 ? '#34d399' : 'var(--dnb-text-2)' } },
                  `🚫 禁止红线（全局与本局边界 · 已生效 ${forbiddenList.length} 条）`),
                h(Icon, {
                  name: 'chevron',
                  size: 12,
                  style: {
                    color: 'var(--dnb-text-3)',
                    transform: redlinesSecCollapsed ? 'none' : 'rotate(90deg)',
                    transition: 'transform 0.16s ease',
                  },
                }),
              ),
              !redlinesSecCollapsed
                ? h(
                    'div',
                    { style: { padding: '0 8px 6px', display: 'flex', flexDirection: 'column', gap: 3 } },
                    forbiddenList.length > 0
                      ? [
                          ...forbiddenList.slice(0, 4).map((item, idx) =>
                            h('div', {
                              key: idx,
                              style: { fontSize: 11, color: 'var(--dnb-text-2)', lineHeight: 1.45, wordBreak: 'break-word' },
                            }, '• ' + (item.length > 88 ? item.slice(0, 88) + '…' : item)),
                          ),
                          forbiddenList.length > 4
                            ? h('div', { key: 'more-redlines', style: { fontSize: 10.5, color: 'var(--dnb-text-3)' } },
                                `…另有 ${forbiddenList.length - 4} 条禁止红线共同生效中`)
                            : null,
                        ]
                      : h('div', { style: { fontSize: 10.5, color: 'var(--dnb-text-3)' } }, '暂未设定禁止红线'),
                  )
                : null,
            ),
          ),
          // 3 Concrete Operational Risks + 4-Tier Permission Behavior
          h(
            'div',
            { style: { fontSize: 11.5, color: 'var(--dnb-text-2)', lineHeight: 1.55 } },
            h('div', { style: { fontWeight: 600, color: 'var(--dnb-text)', marginBottom: 3 } }, '开启后的行为与实操风险：'),
            h('div', { style: { color: '#60a5fa', marginBottom: 4, fontWeight: 600 } },
              `• 当前权限档位联动表现：${INTERVENTION_TIER_DESC[permMode] || INTERVENTION_TIER_DESC.advisor}`),
            h('div', null, '• Token 额外消耗：主对话每轮停顿都将唤醒参谋长核验并可能继续发指令。'),
            h('div', null, '• 对话节奏接管：参谋长会主动插话纠偏与派发下步，点击红色「⏹ 急停」可随时中断。'),
            h('div', null, `• 防死循环熔断：达到 ${normalizeMaxTurnsVal(tm.maxInterventionTurns) === 0 ? '♾️ 无限轮次' : (normalizeMaxTurnsVal(tm.maxInterventionTurns) + ' 轮上限')} 或连续无实际进展将触发熔断保护。`),
          ),
          // Dual Mandatory Disclaimers
          h(
            'div',
            { className: 'dnb-disclaimer-box' },
            h('div', { style: { marginBottom: 4 } },
              h('strong', null, '免责声明 1（模型依赖）：'),
              '参谋长的一切自动审查、强介入驱动、压缩前抢救与红线拦截能力均高度依赖您为参谋长配置的底层大模型能力与上下文质量，不同模型在规划严谨度与遵循指令上的表现存在客观差异。',
            ),
            h('div', null,
              h('strong', null, '免责声明 2（规则冲突）：'),
              '若主会话或当前项目中挂载了过多的系统提示词（System Prompt）、Rules 或硬性规则，可能与本插件的自主干预逻辑产生指令冲突，进而导致介入循环异常、提前熔断或执行偏离预期。',
            ),
          ),
          // Explicit Checkbox Agreement
          h(
            'label',
            { style: { display: 'flex', alignItems: 'flex-start', gap: 7, fontSize: 11.5, color: 'var(--dnb-text)', cursor: 'pointer', lineHeight: 1.45 } },
            h('input', {
              type: 'checkbox',
              checked: Boolean(view.interventionAgreed),
              style: { marginTop: 2 },
              onChange: e => patch({ interventionAgreed: Boolean(e.target.checked) }),
            }),
            '我已核对当前目标、物理驻墙与禁止红线，理解底层模型与宿主提示词规则冲突可能带来偏离，并确认启用主动强介入。',
          ),
          h(
            'div',
            { style: { display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 4 } },
            h('button', {
              type: 'button',
              className: 'dnb-pill',
              style: { height: 32, padding: '0 14px', fontSize: 12.5 },
              onClick: () => patch({ interventionModalOpen: false, interventionAgreed: false }),
            }, '取消'),
            h('button', {
              type: 'button',
              className: 'dnb-primary-btn',
              style: {
                height: 32,
                padding: '0 15px',
                fontSize: 12.5,
                background: '#f59e0b',
                color: '#111',
                fontWeight: 700,
                opacity: (view.interventionAgreed && objLocked && trimmedDraft && !confirmBusy) ? 1 : 0.48,
              },
              disabled: confirmBusy,
              onClick: async () => {
                if (!trimmedDraft) {
                  triggerObjRedFlash('⚠ 未明确核心总目标：请先填写总目标并点击「锁定目标」，方可开启强介入！')
                  return
                }
                if (!objLocked) {
                  triggerObjRedFlash('⚠ 请先点选总目标框右上角的「🔓 锁定目标」按钮，锁定明确目标后才能开启强介入！')
                  return
                }
                if (!view.interventionAgreed) {
                  patch({ notice: '请先勾选下方风险确认框' })
                  return
                }
                setConfirmBusy(true)
                try {
                  const curMax = normalizeMaxTurnsVal(tm.maxInterventionTurns)
                  const ok = await updateSecConfig({
                    tacticalModes: { ...tm, intervention: true, maxInterventionTurns: curMax },
                    confirmedInterventionRisk: true,
                    ...(curMax === 0 ? { confirmedUnlimitedTurns: true } : {}),
                    coreObjective: trimmedDraft,
                    objectiveLocked: true,
                    startImmediately: true,
                  })
                  if (ok) patch({ interventionModalOpen: false, interventionAgreed: false })
                } finally {
                  setConfirmBusy(false)
                }
              },
            }, confirmBusy ? '开启并立即推进中…' : '确认锁定并开启强介入'),
          ),
        ),
      )
    }

